function StrategyBuilder({
  chain,
  onPlaceStrategy,
  disabled,
}: {
  chain: OptionsChain;
  onPlaceStrategy: (
    type: StrategyType,
    legs: StrategyLegInput[],
  ) => Promise<void>;
  disabled: boolean;
}) {
