                        ? optionsChain.calls
                        : optionsChain.puts
                    ).find((l) => l.strike === selectedStrike);
                    return leg ? (leg.ask * contractQty * 100).toFixed(0) : "0";
                  })()}{" "}
                  premium (cash)
                </p>
              )}

              <p className="text-xs text-muted">
                Cash available: ${account.balance.toFixed(0)}
              </p>

              <button
                className={
                  optionSubTab === "call" ? "btn-buy w-full" : "btn-sell w-full"
                }
                disabled={disabled || !selectedStrike}
                onClick={() => handleOptionPlace(optionSubTab)}
              >
