              </button>
            </>
          )}
        </>
      ) : (
        <>
          {!optionsChain ? (
            <p className="text-sm text-muted">Loading options chainâ€¦</p>
          ) : (
            <StrategyBuilder
              chain={optionsChain}
              onPlaceStrategy={onPlaceStrategy}
              disabled={disabled}
            />
          )}
        </>
      )}

      {orderError && <p className="text-xs text-danger">{orderError}</p>}

      {account.status !== "active" && (
        <p className="text-xs text-muted">
          Trading is disabled â€” this account has{" "}
          {account.status === "passed" ? "passed" : "failed"} evaluation.
        </p>
      )}
    </div>
  );
}

