## New file: `lib/trading/margin.ts`

```ts
/**
 * Pure margin & cash-flow engine â€” implements the C5 ledger model.
 *
 * THE MODEL (agreed spec, industry-aligned):
 *   1. ONE cash pool: account.balance. No stored reservations â€” they are
 *      DERIVED live from open positions.
 *   2. UPFRONT FLOW: every option leg exchanges premium at entry.
 *      Long pays ask, short receives bid â€” immediately, into/out of balance.
 *      Equity legs move no cash at entry (leverage model).
 *   3. RESERVATION: locked buying power, held until the workflow closes.
 *        - equity (long or short): notional Ã· leverage
 *        - long-only option structures (longs, debit spreads): 0
 *          (the debit already left the balance â€” it IS the max loss)
 *        - credit structures (verticals, condors): GROSS max outflow
 *          (widest wing Ã— 100). NOTE: deliberately wing-width, NOT
 *          wing-minus-credit â€” the credit is ALREADY inside balance, so
 *          subtracting it here would double-count. The invariant we protect:
 *          balance + upfront + worst-case-settlement â‰¥ 0, always.
 *        - hedged (covered call / protective put): shares' margin only â€”
 *          owned stock covers the short call (industry margin offset).
 *   4. SETTLEMENT FLOW: at close,
 *        - equity books full P&L (no cash moved at entry), while
 *        - options book ONLY the exit-side exchange (entry already moved).
 *      LEDGER LAW (permanent invariant):
 *        upfrontCash(leg) + settlementCashDelta(leg, exit) â‰¡ positionPnl(leg, exit)
 *      Trade rows therefore keep recording positionPnl untouched, and
 *      starting_balance + Î£(trade.pnl) = balance remains THE reconciliation.
 *
 * Rules of this file (same as engine.ts):
 *   Pure. Deterministic. No React, no Supabase, no clocks, no randomness.
 */

import type { InstrumentType, Side } from "./types";
import { positionPnl, CONTRACT_MULTIPLIER } from "./engine";

/** Structural view of any position/order leg. Both DB Position rows and
 *  freshly-priced order legs satisfy this shape. */
export interface MarginLeg {
  instrument_type: InstrumentType;
  side: Side;
  quantity: number;
  strike?: number | null;
  entry_price: number;
}

/** Float-dust guard for money comparisons â€” never trust `a === b` on floats. */
const EPSILON = 1e-6;

/* â”€â”€ UPFRONT CASH â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
 * Positive = credit INTO balance (net short premium received).
 * Negative = debit OUT of balance (net premium paid). Equity: always 0. */
export function upfrontCash(legs: MarginLeg[]): number {
  let cash = 0;
  for (const leg of legs) {
    if (leg.instrument_type === "equity") continue;
    const dir = leg.side === "long" ? 1 : -1;
    cash -= leg.entry_price * leg.quantity * CONTRACT_MULTIPLIER * dir;
  }
  return cash;
}

/* â”€â”€ COVERAGE VALIDATION â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
 * Every net-short option leg must be covered:
 *   - short CALLS may be covered by owned shares (100 shares per contract), or
 *   - any short leg may be covered by a long leg of SAME type & strike.
 * Returns null when sound, else an error naming the naked leg.
 * Regression history: naked shorts are out of product scope (spec v1). */
export function validateCoverage(
  legs: MarginLeg[],
  sharesAvailable = 0,
): string | null {
  const net = new Map<string, number>(); // "type@strike" â†’ net contracts (+long/âˆ’short)
  const meta = new Map<string, { type: "call" | "put"; strike: number }>();

  for (const leg of legs) {
    if (leg.instrument_type === "equity") continue;
    const strike = Math.round((leg.strike ?? 0) * 100) / 100;
    const key = `${leg.instrument_type}@${strike.toFixed(2)}`;
    const dir = leg.side === "long" ? 1 : -1;
    net.set(key, (net.get(key) ?? 0) + dir * leg.quantity);
    meta.set(key, {
      type: leg.instrument_type,
      strike,
    });
  }

  // Consume share coverage on residual short CALLS first.
  let shares = sharesAvailable;
  for (const [key, qty] of net) {
    const m = meta.get(key)!;
    if (m.type === "call" && qty < 0 && shares > 0) {
      const coverable = Math.min(shares / CONTRACT_MULTIPLIER, -qty);
      net.set(key, qty + coverable);
      shares -= coverable * CONTRACT_MULTIPLIER;
    }
  }

  for (const [key, qty] of net) {
    if (qty < -EPSILON) {
      const m = meta.get(key)!;
      return `Uncovered short ${m.type} @ ${m.strike.toFixed(
        2,
      )} â€” short options require share coverage (calls) or a long same-strike counterpart.`;
    }
  }
  return null;
}

/* â”€â”€ MAX OPTION OUTFLOW AT EXPIRY â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
 * Worst-case gross cash OUT at settlement, across all terminal prices.
 * Exact for defined-risk structures: the payoff is piecewise-linear and
 * flat beyond the extreme strikes, so sampling strikes + midpoints +
 * one point outside each edge is exhaustive, not heuristic.
 * Throws on any uncovered short (call validateCoverage first for UI errors).
 * Share-covered short calls are EXCLUDED â€” the stock absorbs them. */
export function optionMaxOutflow(
  legs: MarginLeg[],
  sharesAvailable = 0,
): number {
  const coverageError = validateCoverage(legs, sharesAvailable);
  if (coverageError) throw new Error(coverageError);

  // Effective net map AFTER share coverage consumes residual short calls.
  const eff: Array<{ type: "call" | "put"; strike: number; net: number }> = [];
  const acc = new Map<string, number>();
  const meta = new Map<string, { type: "call" | "put"; strike: number }>();
  let shares = sharesAvailable;

  for (const leg of legs) {
    if (leg.instrument_type === "equity") continue;
    const strike = Math.round((leg.strike ?? 0) * 100) / 100;
    const key = `${leg.instrument_type}@${strike.toFixed(2)}`;
    const dir = leg.side === "long" ? 1 : -1;
    acc.set(key, (acc.get(key) ?? 0) + dir * leg.quantity);
    meta.set(key, { type: leg.instrument_type, strike });
  }
  for (const [key, qty] of acc) {
    const m = meta.get(key)!;
    let netQty = qty;
    if (m.type === "call" && netQty < 0 && shares > 0) {
      const coverable = Math.min(shares / CONTRACT_MULTIPLIER, -netQty);
      netQty += coverable;
      shares -= coverable * CONTRACT_MULTIPLIER;
    }
    if (Math.abs(netQty) > EPSILON) {
      eff.push({ type: m.type, strike: m.strike, net: netQty });
    }
  }

  if (eff.length === 0) return 0;

  const strikes = [...new Set(eff.map((e) => e.strike))].sort((a, b) => a - b);
  const points: number[] = [strikes[0] - 5];
  for (let i = 0; i < strikes.length; i++) {
    points.push(strikes[i]);
    if (i < strikes.length - 1) points.push((strikes[i] + strikes[i + 1]) / 2);
  }
  points.push(strikes[strikes.length - 1] + 5);

  let worst = 0;
  for (const S of points) {
    let delta = 0;
    for (const e of eff) {
      const intrinsic =
        e.type === "call" ? Math.max(0, S - e.strike) : Math.max(0, e.strike - S);
      delta += e.net * intrinsic * CONTRACT_MULTIPLIER;
    }
    worst = Math.min(worst, delta);
  }
  return -worst; // magnitude of the worst outflow (â‰¥ 0)
}

/* â”€â”€ RESERVATION â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
 * Total buying power locked by a workflow's open legs.
 * Shares (long or short): entry notional Ã· leverage. Options: max outflow.
 * Entry notional, deliberately NOT mark-to-market (spec judgment call #1). */
export function reservationFor(legs: MarginLeg[], leverage: number): number {
  let sharesAvailable = 0;
  let equityNotional = 0;
  for (const leg of legs) {
    if (leg.instrument_type !== "equity") continue;
    equityNotional += leg.entry_price * leg.quantity;
    if (leg.side === "long") sharesAvailable += leg.quantity;
  }
  const optionReserve =
    legs.some((l) => l.instrument_type !== "equity")
      ? optionMaxOutflow(legs, sharesAvailable)
      : 0;
  return equityNotional / leverage + optionReserve;
}

/** Free cash after reservations. Display value for the Available column. */
export function availability(balance: number, reserved: number): number {
  return balance - reserved;
}

export interface FundsQuote {
  upfront: number; // +credit / âˆ’debit hitting balance at fill
  reservation: number; // buying power locked while open
  affordable: boolean;
  error: string | null; // coverage problems or shortfall message
}

/** One-call pre-flight check for any placement path (order/option/strategy). */
export function quoteFunds(
  balance: number,
  legs: MarginLeg[],
  leverage: number,
): FundsQuote {
  const sharesAvailable = legs.reduce(
    (s, l) => s + (l.instrument_type === "equity" && l.side === "long" ? l.quantity : 0),
    0,
  );
  const coverageError = validateCoverage(legs, sharesAvailable);
  const upfront = coverageError ? 0 : upfrontCash(legs);
  const reservation = coverageError ? Infinity : reservationFor(legs, leverage);
  const affordable =
    !coverageError && balance + upfront >= reservation - EPSILON;

  let error: string | null = coverageError;
  if (!coverageError && !affordable) {
    const shortfall = reservation - upfront - balance;
    error =
      `Insufficient funds: this workflow locks ${reservation.toFixed(
        2,
      )} in margin against ${upfront >= 0 ? "credit" : "debit"} of ${Math.abs(
        upfront,
      ).toFixed(2)} â€” you are ${shortfall.toFixed(2)} short of the required free cash.`;
  }

  return { upfront, reservation, affordable, error };
}

/* â”€â”€ SETTLEMENT â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
 * Cash delta applied to balance when a leg CLOSES at exitPrice.
 *   equity : full P&L (nothing moved at entry)
 *   options: EXIT-SIDE exchange only â€” the entry premium already moved.
 * Identity (tested): upfrontCash([leg]) + this â‰¡ positionPnl(leg, exit). */
export function settlementCashDelta(
  leg: {
    instrument_type: InstrumentType;
    side: Side;
    quantity: number;
    entry_price: number;
  },
  exitPrice: number,
): number {
  if (leg.instrument_type === "equity") {
    return positionPnl(leg, exitPrice);
  }
  const dir = leg.side === "long" ? 1 : -1;
  return dir * exitPrice * leg.quantity * CONTRACT_MULTIPLIER;
}
